// cart_state.h is generated by `blyt build` and made available via
// @CART_GENERATED_C@, giving this file access to the S_STATE_* constants
// without any C glue code.

var sFrame: Int32 = 0

// --- Cart entry points ----------------------------------------------------

@_cdecl("blyt_cart_on_new_state")
public func cartOnNewState() {
    var slot: Int32 = -1
    blyt_buffer_alloc_slot(S_STATE, &slot)
    blyt_buffer_set_i32(S_STATE, 0, S_STATE_FRAME, 0)
    blyt_buffer_set_i32(S_STATE, 0, S_STATE_X, 160)
    blyt_buffer_set_i32(S_STATE, 0, S_STATE_Y, 120)
    blyt_console_debug("init player pos: 160, 120")
}

@_cdecl("blyt_cart_init")
public func cartInit() {
    sFrame = 0
}

@_cdecl("blyt_cart_on_save_state")
public func cartOnSaveState() {
    blyt_buffer_set_i32(S_STATE, 0, S_STATE_FRAME, sFrame)
}

@_cdecl("blyt_cart_on_load_state")
public func cartOnLoadState(_ info: blyt_load_info_t) {
    sFrame = blyt_buffer_get_i32(S_STATE, 0, S_STATE_FRAME)
}

@_cdecl("blyt_cart_update")
public func cartUpdate() {
    sFrame &+= 1
    if sFrame % 10 == 0 {
        let x = (blyt_buffer_get_i32(S_STATE, 0, S_STATE_X) &+ 1) % 320
        let y = (blyt_buffer_get_i32(S_STATE, 0, S_STATE_Y) &+ 1) % 240
        blyt_buffer_set_i32(S_STATE, 0, S_STATE_X, x)
        blyt_buffer_set_i32(S_STATE, 0, S_STATE_Y, y)
        blyt_debug_frame_pos("update", sFrame, x, y)
    }
}

@_cdecl("blyt_cart_draw")
public func cartDraw() {
    if sFrame % 10 == 0 {
        let x = blyt_buffer_get_i32(S_STATE, 0, S_STATE_X)
        let y = blyt_buffer_get_i32(S_STATE, 0, S_STATE_Y)
        blyt_debug_frame_pos("draw", sFrame, x, y)
    }
}
